import React, { useState } from "react";
import { FaUserCircle, FaUpload, FaEnvelope, FaPhone, FaMapMarkerAlt } from "react-icons/fa";
import "../assets/css/profile.css";

const Profile = () => {
  const [photo, setPhoto] = useState(null);

  const handlePhotoChange = (e) => setPhoto(e.target.files[0]);

  const handlePhotoUpload = () => {
    if (!photo) return alert("Please select a photo first!");
    alert("Photo uploaded (demo).");
  };

  return (
    <div className="profile-dashboard">
      <div className="profile-header">
        <h2>My Profile</h2>
      </div>

      <div className="profile-card">
        <div className="profile-photo-section">
          <div className="profile-photo-wrapper">
            <FaUserCircle className="profile-image default-avatar" />
            <label className="upload-icon-btn">
              <FaUpload />
              <input type="file" hidden onChange={handlePhotoChange} />
            </label>
          </div>
          <div className="upload-controls">
            <button onClick={handlePhotoUpload}>Upload Photo</button>
          </div>
        </div>

        <div className="profile-info-section">
          <div className="info-item">
            <FaEnvelope className="info-icon" />
            <div className="info-text">
              <h3>Email</h3>
              <p>admin@example.com</p>
            </div>
          </div>

          <div className="info-item">
            <FaPhone className="info-icon" />
            <div className="info-text">
              <h3>Phone</h3>
              <p>+91 9876543210</p>
            </div>
          </div>

          <div className="info-item">
            <FaMapMarkerAlt className="info-icon" />
            <div className="info-text">
              <h3>Location</h3>
              <p>New Delhi, India</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Profile;
